    def minWindow(self, s: str, t: str) -> str:
        need = Counter(t)
        best = ""
        for l in range(len(s)):
            have = Counter()
            for r in range(l, len(s)):
                have[s[r]] += 1
                if all(have[c] >= need[c] for c in need):
                    if best == "" or r - l + 1 < len(best):
                        best = s[l:r + 1]
                    break
        return best

